package mrpapermoon.whisperimport androidx.annotation.MainThreadimport androidx.lifecycle.ViewModelimport dagger.hilt.android.lifecycle.HiltViewModelimport io.github.oshai.kotlinlogging.KotlinLoggingimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport mrpapermoon.whisper.navigation.NavigationActionimport mrpapermoon.whisper.navigation.NavigationScreenimport mrpapermoon.whisper.navigation.NavigationTabimport javax.inject.Inject@HiltViewModelclass SharedViewModel @Inject constructor() : ViewModel(), NavigationAction {	private val logger = KotlinLogging.logger {}	private val _verticalNavigationState = MutableStateFlow(NavigationScreen.DEFAULT)	val verticalNavigationState: StateFlow<NavigationScreen> = _verticalNavigationState.asStateFlow()	private val _horizontalNavigationState = MutableStateFlow<NavigationTab?>(null)	val horizontalNavigationState: StateFlow<NavigationTab?> = _horizontalNavigationState.asStateFlow()	private val navigationPath = ArrayDeque<NavigationScreen>()	val path: String		get() = "mrpapermoon.whisper://${navigationPath.joinToString("/")}"	@MainThread	override fun navigateTo(screen: NavigationScreen) {		navigationPath += screen		internalNavigation(screen)	}	@MainThread	override fun popBack() {		try {			navigationPath.removeLast()		} catch (e: NoSuchElementException) {			logger.error(e) { "Unsupported action" }		} finally {			val last = navigationPath.lastOrNull()				?: NavigationScreen.DEFAULT					.also { navigationPath += it }			internalNavigation(last)		}	}	private fun internalNavigation(screen: NavigationScreen) {		_verticalNavigationState.value = screen		_horizontalNavigationState.value = when (screen) {			is NavigationScreen.main -> NavigationTab.MAIN			NavigationScreen.profile -> NavigationTab.PROFILE			NavigationScreen.settings -> NavigationTab.SETTINGS			NavigationScreen.splash -> null		}	}}